import type { Metadata } from "next";
import Image from "next/image";
import Link from "next/link";
import { notFound } from "next/navigation";
import { Suspense } from "react";
import { Clock, XCircle } from "lucide-react";
import { db } from "@/lib/db";
import { requireUser, isAdmin } from "@/lib/auth";
import { formatINR } from "@/lib/money";
import { formatDate } from "@/lib/utils";
import { PaymentBadge } from "@/components/PaymentBadge";
import { OrderStatusBadge, ORDER_STEPS } from "@/components/OrderStatus";
import { CancelOrder } from "@/components/store/CancelOrder";
import { SuccessCheck } from "@/components/store/SuccessCheck";

export const metadata: Metadata = { title: "Order details", robots: { index: false } };

async function OrderContent({ params, searchParams }: Pick<PageProps<"/order/[orderNumber]">, "params" | "searchParams">) {
  const { orderNumber } = await params;
  const placed = (await searchParams).placed === "1";
  const user = await requireUser(`/order/${orderNumber}`);
  const order = await db.order.findUnique({ where: { orderNumber }, include: { items: true, events: { orderBy: { createdAt: "asc" } } } });
  if (!order || (order.userId !== user.id && !isAdmin(user))) notFound();
  const addr = order.shippingAddress as Record<string, string>;
  const stepIndex = ORDER_STEPS.indexOf(order.status as (typeof ORDER_STEPS)[number]);

  return (
    <div className="space-y-6">
      {placed && order.paidAt && (
        <div className="animate-scale-in flex items-start gap-4 rounded-lg border border-success/30 bg-success/10 p-5">
          <SuccessCheck />
          <div>
            <h1 className="font-display text-2xl font-semibold">Thank you! Your order is confirmed.</h1>
            <p className="text-sm">Order <span className="font-semibold">#{order.orderNumber}</span> · a confirmation has been recorded for {order.email}. We’ll WhatsApp you when it ships.</p>
          </div>
        </div>
      )}
      {!order.paidAt && order.status === "PENDING_PAYMENT" && (
        <div className="flex items-start gap-3 rounded-lg border border-warn/30 bg-warn/10 p-5 text-sm">
          <Clock className="h-6 w-6 shrink-0 text-warn" aria-hidden />
          <p>We’re waiting for payment confirmation from your bank. This page will update once Razorpay confirms it — usually within a few minutes.</p>
        </div>
      )}
      {(order.status === "CANCELLED" || order.status === "REFUNDED") && order.paidAt && (
        <div className="animate-fade-up flex items-start gap-3 rounded-lg border border-line bg-white p-5 text-sm">
          <XCircle className="h-6 w-6 shrink-0 text-ink-soft" aria-hidden />
          <div>
            <p className="font-semibold">This order has been cancelled.</p>
            <p className="text-muted">
              {order.events.find((e) => e.status === "REFUND_INITIATED")?.note ?? "Any amount paid online will be refunded to your original payment method."} Refunds reach your account in 5–7 working days.
            </p>
          </div>
        </div>
      )}
      {order.status === "PAYMENT_FAILED" && (
        <div className="flex items-start gap-3 rounded-lg border border-danger/30 bg-danger/10 p-5 text-sm">
          <XCircle className="h-6 w-6 shrink-0 text-danger" aria-hidden />
          <p>Payment for this order failed. If money was debited, it will be auto-refunded by your bank within 5–7 working days. <Link href="/cart" className="font-semibold underline">Try again from your cart</Link>.</p>
        </div>
      )}

      <div className="card p-5">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <div>
            <p className="text-sm text-muted">Order placed {formatDate(order.createdAt, true)}</p>
            <p className="font-display text-xl font-semibold">#{order.orderNumber}</p>
          </div>
          <div className="flex items-center gap-3">
            <OrderStatusBadge status={order.status} />
            {order.paidAt && <Link href={`/order/${order.orderNumber}/invoice`} className="btn-outline text-sm">GST Invoice</Link>}
          </div>
        </div>
        {stepIndex >= 0 && (
          <ol className="mt-6 grid grid-cols-4 gap-2 text-center text-xs">
            {ORDER_STEPS.map((s, i) => (
              <li key={s} className={i <= stepIndex ? "font-semibold text-success" : "text-muted"}>
                <div className="mx-auto mb-1 h-2 overflow-hidden rounded-full bg-line">
                  {i <= stepIndex && <div className="h-full origin-left animate-[grow-x_600ms_var(--ease-out)_both] rounded-full bg-success" style={{ animationDelay: `${i * 250}ms` }} />}
                </div>
                {s.charAt(0) + s.slice(1).toLowerCase()}
              </li>
            ))}
          </ol>
        )}
        {order.trackingNumber && <p className="mt-4 text-sm">Tracking: <span className="font-semibold">{order.courier} {order.trackingNumber}</span></p>}
        {order.status === "PAID" && order.userId === user.id && <div className="mt-4"><CancelOrder orderNumber={order.orderNumber} /></div>}
      </div>

      <div className="grid gap-6 md:grid-cols-[1fr_320px]">
        <div className="card divide-y divide-line p-5">
          {order.items.map((it) => (
            <div key={it.id} className="flex gap-4 py-3">
              <div className="relative h-20 w-20 shrink-0 rounded bg-paper">{it.image && <Image src={it.image} alt="" fill sizes="80px" className="object-contain p-1" />}</div>
              <div className="flex-1 text-sm">
                <p className="font-medium">{it.name}</p>
                {it.engravingText && <p className="text-brass">Engraving: “{it.engravingText}”</p>}
                <p className="text-muted">Qty {it.quantity} × {formatINR(it.unitPrice)}</p>
              </div>
              <p className="font-semibold">{formatINR(it.unitPrice * it.quantity)}</p>
            </div>
          ))}
        </div>
        <div className="space-y-4">
          <div className="card p-5 text-sm">
            <p className="mb-1 font-semibold">Shipping address</p>
            <p>{addr.name}<br />{addr.line1}{addr.line2 && <>, {addr.line2}</>}<br />{addr.city}, {addr.state} – {addr.pincode}<br />{addr.phone}</p>
          </div>
          <div className="card space-y-1.5 p-5 text-sm">
            <p className="mb-1 font-semibold">Payment</p>
            <PaymentBadge method={order.paymentMethod} details={order.paymentDetails as Record<string, string | number | null> | null} />
            <div className="flex justify-between pt-2"><span>Items</span><span>{formatINR(order.subtotal)}</span></div>
            {order.discount > 0 && <div className="flex justify-between text-success"><span>Discount</span><span>−{formatINR(order.discount)}</span></div>}
            <div className="flex justify-between"><span>Delivery</span><span>{order.shippingFee ? formatINR(order.shippingFee) : "FREE"}</span></div>
            <div className="flex justify-between border-t border-line pt-2 font-semibold"><span>Total</span><span>{formatINR(order.total)}</span></div>
          </div>
        </div>
      </div>
      <Link href="/account" className="text-sm font-semibold text-maroon hover:underline">← All my orders</Link>
    </div>
  );
}

export default function OrderPage({ params, searchParams }: PageProps<"/order/[orderNumber]">) {
  return (
    <div className="container-x py-6">
      <Suspense fallback={<div className="h-96 skeleton rounded-xl" />}>
        <OrderContent params={params} searchParams={searchParams} />
      </Suspense>
    </div>
  );
}
